void process_buf(const char *buf, size_t size) {
    const char *p = buf;
    const char *end = buf + size;
    while (p < end && *p != '\n') p++;
    if (p < end) p++;

    size_t rem = (size_t)(end - p);
    if (rem < 65536) {
        ThreadArg ta;
        ta.start = p;
        ta.end = end;
